import{_ as a,o,c as t,a0 as s}from"./chunks/framework.DqMqoJl9.js";const u=JSON.parse('{"title":"安装开发工具","description":"","frontmatter":{},"headers":[],"relativePath":"guides/install-ide.md","filePath":"guides/install-ide.md"}'),d={name:"guides/install-ide.md"};function c(i,e,r,n,l,p){return o(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="安装开发工具" tabindex="-1">安装开发工具 <a class="header-anchor" href="#安装开发工具" aria-label="Permalink to &quot;安装开发工具&quot;">​</a></h1><p>优先使用你熟悉的开发工具。</p><h2 id="visual-studio-code" tabindex="-1">Visual Studio Code <a class="header-anchor" href="#visual-studio-code" aria-label="Permalink to &quot;Visual Studio Code&quot;">​</a></h2><p>免费、可配置性强。</p><p><strong>1. 安装 Go 工具集</strong></p><p>按 <code>Shift + Ctrl/Cmd + P</code>，输入 <code>Go: Install/Update Tools</code>，勾选所有项后确认。</p><p><strong>2. 安装插件</strong></p><p>点击侧边栏的「扩展」进入插件市场：</p><ul><li>搜索 <code>Go</code>，安装 <code>Go Team at Google</code> 发布的插件</li><li>搜索 <code>Tooltitude for Go</code>，安装 <code>Tooltitude Team</code> 发布的插件</li></ul><p><strong>3. 调试配置</strong></p><p>示例仓库已经准备好五个节点的调试配置，可以直接参考：</p><ul><li><a href="https://github.com/cherry-game/examples/blob/master/.vscode/launch.json" target="_blank" rel="noreferrer">examples/.vscode/launch.json</a></li></ul><p>配置好后在「运行和调试」面板就能看到 <code>demo-chat</code>、<code>demo-gorm</code>、<code>gc-master</code>、<code>gc-center</code>、<code>gc-web-1</code>、<code>gc-gate-1</code>、<code>gc-game-10001</code> 等启动项。</p><h2 id="goland" tabindex="-1">GoLand <a class="header-anchor" href="#goland" aria-label="Permalink to &quot;GoLand&quot;">​</a></h2><p>收费，但易用性好。</p><p>推荐使用 <a href="https://www.jetbrains.com/go/" target="_blank" rel="noreferrer">GoLand</a> 进行开发，编码和调试都很方便。</p><p>调试多节点示例时，在 <code>Run/Debug Configurations</code> 里配置 <code>Program arguments</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>master --path=./config/demo-cluster.json --node=gc-master</span></span></code></pre></div><p>五个节点各配一个，分别填 <code>master</code> / <code>center</code> / <code>web</code> / <code>gate</code> / <code>game</code> 作为第一个参数。</p><h2 id="可选-查看-nats-消息" tabindex="-1">可选：查看 NATS 消息 <a class="header-anchor" href="#可选-查看-nats-消息" aria-label="Permalink to &quot;可选：查看 NATS 消息&quot;">​</a></h2><p>开发集群功能时，用 <a href="https://github.com/nats-io/natscli" target="_blank" rel="noreferrer">nats CLI</a> 可以订阅 subject 观察节点间消息：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nats</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;cherry.&gt;&quot;</span></span></code></pre></div><p>对应 Cherry 的 subject 命名规则见 <a href="/core/cluster.html#nats-subject-格式">通信 &amp; 集群</a>。</p>',23)])])}const g=a(d,[["render",c]]);export{u as __pageData,g as default};
